function drawMorpekoHamster(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.4;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.05 * breathSin;
  const sX = 1.0 - 0.025 * breathSin;
  const by = -Math.abs(breathSin) * 3.0;

  const earWiggle = Math.sin(breathPhase - 0.45) * 2.0;

  // Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 26 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // Tai lá nhỏ
  ctx.fillStyle = '#a16207';
  ctx.beginPath(); ctx.ellipse(-16, by - 22 + earWiggle, 6, 12, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.ellipse(16, by - 22 - earWiggle, 6, 12, 0, 0, Math.PI * 2); ctx.fill();

  // Thân phân mảng 3 màu
  ctx.fillStyle = '#a16207';
  ctx.beginPath(); ctx.ellipse(-8, by + 12, 18 * sX, 22 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.ellipse(8, by + 12, 18 * sX, 22 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(0, by + 12, 14 * sX, 21 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(0, by + 24, 18 * sX, 12 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Đầu 3 mảng
  ctx.fillStyle = '#a16207';
  ctx.beginPath(); ctx.ellipse(-7, by - 6, 15 * sX, 17 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.ellipse(7, by - 6, 15 * sX, 17 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef08a';
  ctx.beginPath(); ctx.ellipse(0, by - 6, 11 * sX, 16 * sY, 0, 0, Math.PI * 2); ctx.fill();

  // Chân
  ctx.beginPath(); ctx.roundRect(-14, by + 32, 9, 6, 3); ctx.fill();
  ctx.beginPath(); ctx.roundRect(5, by + 32, 9, 6, 3); ctx.fill();

  // Má hồng
  ctx.fillStyle = '#f472b6';
  ctx.beginPath(); ctx.arc(-15, by + 2, 6, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(15, by + 2, 6, 0, Math.PI * 2); ctx.fill();

  // Mắt đen
  if (!blink) {
    ctx.fillStyle = '#1e293b';
    ctx.beginPath(); ctx.ellipse(-9, by - 6, 4, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.ellipse(9, by - 6, 4, 6, 0, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-10, by - 8, 2, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(8, by - 8, 2, 0, Math.PI * 2); ctx.fill();
  }

  // Miệng & răng
  ctx.fillStyle = '#881337';
  ctx.beginPath(); ctx.moveTo(0, by + 6); ctx.lineTo(-6, by + 1); ctx.lineTo(6, by + 1); ctx.fill();
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(-2, by + 1, 4, 3);

  // Tay cầm quả mọng
  ctx.fillStyle = '#334155';
  ctx.beginPath(); ctx.roundRect(12, by + 4, 10, 8, 3); ctx.fill();
  ctx.fillStyle = '#84cc16';
  ctx.beginPath(); ctx.arc(22, by + 6, 4, 0, Math.PI * 2); ctx.fill();

  ctx.restore();
}
